-- bible-text.db schema
-- Master build artifact: NOT committed (see .gitignore). Regenerated by build.py
-- from the open-data/ submodules. Contains all license tiers (including
-- 'restricted-nc' and 'unknown') -- tier filtering happens at export time,
-- not at ingestion time, so nothing here should be assumed safe to publish
-- without checking works.license_tier first.

CREATE TABLE works (
    work_id TEXT PRIMARY KEY,       -- unique per DISTRIBUTION, e.g. 'scrollmapper-KJV', 'morphhb-wlc'
    translation_code TEXT,          -- canonical short code, e.g. 'KJV' -- may repeat across work_id
                                     -- when the same nominal translation comes from multiple sources
    title TEXT,
    language TEXT,                  -- 'heb', 'grc', 'eng', etc.

    -- heritage: exactly where this distribution came from and when
    source_id TEXT,                 -- submodule name, e.g. 'scrollmapper-bible-databases'
    source_repo_url TEXT,           -- our fork URL
    source_commit TEXT,             -- submodule git commit hash at ingestion time
    ingested_at TEXT,               -- ISO date of this build

    -- licensing: verbatim as reported by the source, plus our classification
    license TEXT,                   -- verbatim string, e.g. 'Creative Commons: BY-NC-SA 4.0'
    license_tier TEXT NOT NULL,     -- 'open' | 'restricted-nc' | 'unknown' | 'quotation-only'
    attribution TEXT,

    -- what (book, chapter, verse) MEANS for this work: 'masoretic' | 'lxx' | 'english'.
    -- Two works with different schemes disagree about whole chapters -- MT Joel 3:1 is EN Joel
    -- 2:28, LXX Ps 22 is EN Ps 23 -- and comparing them without aligning returns the wrong verse
    -- with no error. Set by set_versification() in build.py; align with versification.align().
    versification TEXT NOT NULL DEFAULT 'english',
    notes TEXT                      -- e.g. caveats like the strongs/TWOT one, or classification rationale
);

CREATE TABLE verses (
    work_id TEXT NOT NULL REFERENCES works(work_id),
    book TEXT NOT NULL,             -- OSIS book code (GEN, EXO, ... MATT, ... REV)
    chapter INTEGER NOT NULL,
    verse INTEGER NOT NULL,
    text TEXT NOT NULL
);
CREATE INDEX idx_verses_ref ON verses(book, chapter, verse);
CREATE INDEX idx_verses_work ON verses(work_id);
-- One row per reference per work, enforced rather than assumed. It was assumed for a long time
-- and it was not true: upstream scrollmapper ships each verse several times over with differing
-- whitespace, which left 28674 references carrying two or three rows across 38 works, and
-- lookup_verse's fetchone() silently returned whichever one SQLite reached first.
-- NOTE this makes the tuple unique WITHIN a work only. It is still not an identity ACROSS works
-- -- see works.versification above.
CREATE UNIQUE INDEX idx_verses_unique ON verses(work_id, book, chapter, verse);

CREATE TABLE morphology (           -- word-by-word tags on original-language verses
    work_id TEXT NOT NULL REFERENCES works(work_id),
    book TEXT NOT NULL,
    chapter INTEGER NOT NULL,
    verse INTEGER NOT NULL,
    word_position INTEGER NOT NULL,
    surface_form TEXT,
    strongs_id TEXT,                -- bare numeric, no G/H prefix; occasionally compound ('1537+4053')
                                     -- for a single word covered by multiple Strong's numbers -- lookups
                                     -- on a specific number need to account for that, not just '='
    morph_code TEXT,
    cantillation_level TEXT,
    lemma TEXT,                     -- dictionary form, only populated by macula-* work_ids so far
    gloss TEXT,                     -- short English gloss, only populated by macula-* work_ids so far
    domain_code TEXT,               -- semantic domain code: Louw-Nida 'NN.NN' (Greek) or SDBH
                                     -- lexdomain/contextualdomain (Hebrew); only macula-* work_ids so far

    -- Syntax / coreference, from the MACULA TSVs' own columns. macula-* work_ids only; every other
    -- source leaves these NULL. Coverage is genuinely partial (MACULA annotates what it annotates):
    -- word_class ~100%, sub_type 33% (Greek) / 73% (Hebrew), syntactic_role 33% (Greek only),
    -- state 28% (Hebrew only), frame 14-18%, subject_ref 9-12%, referent 10%. A NULL means
    -- "not annotated", NOT "no such role" -- don't infer absence from it.
    node_id TEXT,                   -- MACULA's own xml:id for this word, NORMALIZED TO DIGITS ONLY.
                                     -- The source ids carry a corpus prefix ('n' for the Greek NT,
                                     -- 'o' for the Hebrew OT) but the subjref/referent pointers below
                                     -- are inconsistent about it: Greek pointers keep the 'n'
                                     -- ('n40001018011'), Hebrew pointers drop the 'o' ('010010050021')
                                     -- while the Hebrew xml:id keeps it ('o010010050061'). Storing
                                     -- everything digits-only is what makes a pointer join work at all;
                                     -- joined raw, Hebrew coreference silently returns zero rows.
    word_class TEXT,                -- MACULA 'class': noun, verb, det, conj, pron, prep, adj, adv...
    syntactic_role TEXT,            -- MACULA 'role', Greek only: s=subject, v=verb, o=object,
                                     -- io=indirect object, adv=adverbial, p=predicate, vc=copula
    sub_type TEXT,                  -- MACULA 'type'. Greek: common/proper/personal/demonstrative/...
                                     -- Hebrew: doubles as verb conjugation (qatal, wayyiqtol, yiqtol,
                                     -- participle active, ...) -- useful, and not obvious from the name
    state TEXT,                     -- Hebrew only: absolute / construct / determined (construct chains)
    extant INTEGER,                 -- dss-* only: 1 when NO sign in the word is reconstructed or
                                     -- uncertain. Only 33% of biblical scroll words qualify -- 46%
                                     -- of signs are a modern editor's reconstruction -- so a scroll
                                     -- reading that differs from the Masoretic is only evidence
                                     -- when this is set. Everything else is a tear.
    frame TEXT,                     -- verbal argument frame, e.g. 'A0:n40001018011' (A0 = agent, and
                                     -- the value points at a node_id). Pointers here are NOT normalized
                                     -- -- the field is a compound string, parse before joining
    subject_ref TEXT,               -- node_id of this verb's subject; the payoff is implicit subjects,
                                     -- where Greek/Hebrew inflection carries the subject with no
                                     -- separate word to point at in the verse itself
    referent TEXT                   -- node_id this word refers back to: Greek 'referent', Hebrew
                                     -- 'participantref' (different column names, same idea, merged here)
);
CREATE INDEX idx_morph_ref ON morphology(book, chapter, verse);
CREATE INDEX idx_morph_strongs ON morphology(strongs_id);
CREATE INDEX idx_morph_domain ON morphology(domain_code);
CREATE INDEX idx_morph_node ON morphology(work_id, node_id);   -- pointer resolution for subject_ref/referent
CREATE INDEX idx_morph_role ON morphology(syntactic_role);

CREATE TABLE literary_units (       -- paragraph/pericope boundaries, keyed to the Masoretic text's
                                     -- own markers (samekh/pe), not modern chapter divisions
    work_id TEXT NOT NULL REFERENCES works(work_id),
    book TEXT NOT NULL,
    unit_type TEXT NOT NULL,        -- 'paragraph' | 'pericope'
    start_chapter INTEGER NOT NULL, start_verse INTEGER NOT NULL,
    end_chapter INTEGER NOT NULL, end_verse INTEGER NOT NULL
);
CREATE INDEX idx_units_ref ON literary_units(book, start_chapter, start_verse);

CREATE TABLE notes (                -- edition-bundled translator/study notes
    work_id TEXT NOT NULL REFERENCES works(work_id),
    book TEXT NOT NULL,
    chapter INTEGER NOT NULL,
    verse INTEGER NOT NULL,
    note_type TEXT,                 -- 'translator' | 'study' | other
    text TEXT NOT NULL
);
CREATE INDEX idx_notes_ref ON notes(book, chapter, verse);

CREATE TABLE dss_variants (         -- where a Dead Sea Scroll reads something the Masoretic does
                                    -- not, derived at build time. Compared at LEMMA level: the
                                    -- scrolls' fuller spelling and their habit of splitting
                                    -- prefixes into separate words swamp a surface comparison
                                    -- (99% of verses "differ"), and both vanish at lemma level
                                    -- (28%).
    work_id TEXT NOT NULL REFERENCES works(work_id),   -- the scroll
    book TEXT NOT NULL, chapter INTEGER NOT NULL, verse INTEGER NOT NULL,
    lemma TEXT NOT NULL,             -- an extant scroll lemma the Masoretic verse does not carry
    extant_words INTEGER NOT NULL,   -- how much of the VERSE survives. Weigh a reading by it, but
                                     -- do not filter on it: what matters is that the differing word
                                     -- itself is extant, and the surrounding context being torn
                                     -- does not make a legible word less legible. Requiring five
                                     -- surviving words discarded Deuteronomy 32:8 in 4Q37 -- the
                                     -- best-known variant in the corpus -- where only four survive
                                     -- but 'sons of God' is among them, whole.
    -- ONE DIRECTION ONLY, deliberately. A lemma the scroll has and the Masoretic lacks is a
    -- reading. A lemma the Masoretic has and the scroll lacks is almost always damage, and
    -- recording it would manufacture omissions out of holes in the leather.
    CHECK (extant_words >= 2)
);
CREATE INDEX idx_dssvar_ref ON dss_variants(book, chapter, verse);

CREATE TABLE scripture_links (      -- derived here rather than ingested: see quotations.py for
                                    -- the method and the audits that set each threshold.
    -- The classes are NOT equivalent evidence and must never be merged into one score:
    --   'quotation-greek'   NT Greek quoting LXX Greek. A textual fact -- author and translator
    --                       were writing the same language, so the quotation is the same words.
    --   'inner-biblical'    Hebrew OT quoting Hebrew OT. Equally a textual fact, and no translation
    --                       stands between the two sides.
    --   'quotation-hebrew'  a Hebrew NT matching the Hebrew OT. CANDIDATES ONLY. Delitzsch is a
    --                       19th-century translation, so a match says that a Hebraist judged this
    --                       to be a quotation and rendered it accordingly -- informed opinion, not
    --                       evidence. Useful because it catches quotations the Greek misses, where
    --                       the NT follows the Hebrew rather than the LXX. Verify in Greek before
    --                       any of it carries weight in a study.
    --   'quotation-crosslang' NT Greek against the Hebrew OT, through a Greek->Hebrew lexicon learned
    --                       from the Septuagint's own translation choices. Only in verses that cite
    --                       Scripture, only the best match, only with a clear margin: it reaches the
    --                       quotations that follow the Hebrew where the Septuagint differs.
    link_type TEXT NOT NULL,
    from_work TEXT NOT NULL REFERENCES works(work_id),
    from_book TEXT NOT NULL, from_chapter INTEGER NOT NULL, from_verse INTEGER NOT NULL,
    to_work TEXT NOT NULL REFERENCES works(work_id),
    to_book TEXT NOT NULL, to_chapter INTEGER NOT NULL, to_verse INTEGER NOT NULL,
    -- graded four ways, and deliberately not combined into one number
    shared_ngrams INTEGER NOT NULL,  -- n-grams the two verses share
    containment REAL NOT NULL,       -- share of the quoting verse's n-grams that are shared
    longest_run INTEGER NOT NULL,    -- longest contiguous shared token run. Interpretable -- a
                                     -- reader can go and count it -- but it breaks at the first
                                     -- inserted or omitted word, and adapted quotation is normal
    alignment INTEGER NOT NULL,      -- Smith-Waterman local alignment, which tolerates those edits.
                                     -- The primary strength measure: Luke 4:18 omits a clause from
                                     -- Isaiah 61:1 and runs only 6, under the run threshold, while
                                     -- aligning at 25 -- above verbatim Hebrews 10:5
    idf_overlap REAL NOT NULL,       -- shared n-grams weighted by rarity in the source corpus, so
                                     -- a shared "and it came to pass" stops counting like a shared
                                     -- rare phrase
    corroborated INTEGER NOT NULL,   -- 1 when openbible's cross-references independently agree
    -- the english-scheme reference for to_*, so a caller need not re-align. NULL where the passage
    -- has no English counterpart (LXX Jeremiah 30, the Proverbs 24 tail).
    to_english_chapter INTEGER, to_english_verse INTEGER,
    -- Added 2026-10 (docs/dev/link-detection-research.md). `strong` is what the reader sees: 1 when
    -- any rule in quotations.py admits the pair. `basis` names every rule that did, so a link can
    -- always be explained -- 'alignment', 'unique-phrases', 'formula+phrases', 'lemma', 'lemma-run',
    -- 'crosslang', 'rare-lemmas', 'hebrew-nt'. Never a blend: each rule stands on its own measure.
    strong INTEGER NOT NULL DEFAULT 0,
    basis TEXT,
    unique_phrases INTEGER,          -- Greek: shared phrases found in exactly one Septuagint verse
    lemma_score REAL                 -- inner-biblical and crosslang: the rarity-weighted alignment
);
CREATE INDEX idx_link_from ON scripture_links(link_type, from_book, from_chapter, from_verse);
CREATE INDEX idx_link_to ON scripture_links(link_type, to_book, to_chapter, to_verse);

CREATE TABLE cross_references (     -- verse-to-verse, translation-independent
    work_id TEXT NOT NULL REFERENCES works(work_id),
    from_book TEXT NOT NULL, from_chapter INTEGER NOT NULL, from_verse INTEGER NOT NULL,
    to_book TEXT NOT NULL, to_chapter INTEGER NOT NULL,
    to_verse_start INTEGER NOT NULL, to_verse_end INTEGER NOT NULL,
    votes INTEGER
);
CREATE INDEX idx_xref_from ON cross_references(from_book, from_chapter, from_verse);

CREATE TABLE word_alignment (       -- which original-language word each English word renders,
                                    -- from unfoldingWord's ULT and the Berean Interlinear (BSB).
                                    -- Filter on work_id: the two are separate
                                    -- translations. Nothing else in this database
                                    -- answers "which Hebrew word is this English word?" -- the
                                    -- morphology table describes original words, and the
                                    -- translations sit beside them unlinked.
    work_id TEXT NOT NULL REFERENCES works(work_id),   -- the English side: uw-ult or berean-bib
    book TEXT NOT NULL, chapter INTEGER NOT NULL, verse INTEGER NOT NULL,
    english TEXT NOT NULL,           -- the English words this alignment frame encloses
    content TEXT NOT NULL,           -- the original-language word they render
    lemma TEXT, strong TEXT, morph TEXT,  -- berean-bib: no lemma, strong unpadded ('H7225'),
                                          -- morph the tables' own parsing code
    -- MANY-TO-MANY, deliberately. USFM nests alignment frames, so two original words can enclose
    -- one English phrase and one original word can enclose several English words. Each frame
    -- becomes its own row rather than being flattened: Genesis 1:1's "the heavens" is genuinely
    -- rendering both אֵת and הַשָּׁמַיִם, and picking one would invent a precision the data does
    -- not have.
    occurrence INTEGER               -- which occurrence of `content` within the verse
);
CREATE INDEX idx_align_ref ON word_alignment(book, chapter, verse);
CREATE INDEX idx_align_strong ON word_alignment(strong);

CREATE TABLE versification_map (  -- per-verse Hebrew numbering, recorded by the source itself
                                    -- rather than inferred. UHB numbers verses the ULT's (English)
                                    -- way and carries the Masoretic number alongside in a \va
                                    -- marker, for 1,970 verses across 27 books. That is strictly
                                    -- better evidence than versification.superscription_offset(),
                                    -- which infers a whole-chapter shift from two works' verse
                                    -- counts: this is stated per verse, and it covers cases the
                                    -- scheme-level align() gets wrong outright (English Jonah 1:17
                                    -- is Hebrew Jonah 2:1, and English Job 41:2 is Hebrew Job
                                    -- 40:26 -- align() returns the reference unchanged for both).
    work_id TEXT NOT NULL REFERENCES works(work_id),
    book TEXT NOT NULL,
    chapter INTEGER NOT NULL,        -- as this work numbers it
    verse INTEGER NOT NULL,
    alt_scheme TEXT NOT NULL,        -- the scheme alt_chapter/alt_verse are numbered in
    alt_chapter INTEGER NOT NULL,
    alt_verse INTEGER NOT NULL,
    -- \va sometimes gives "32:1" and sometimes a bare "1" even where the chapter also rolls over
    -- (Daniel 5:31, Jonah 1:17), so the chapter is not always stated and cannot be taken on trust.
    -- 'explicit'         the source named chapter and verse outright.
    -- 'verse+verified'   \va gave the verse; the chapter was resolved by finding which candidate
    --                    the WLC text actually agrees with, so both halves are checked.
    -- 'verse+unverified' \va gave the verse but no candidate chapter matched the WLC. The chapter
    --                    is an unconfirmed inference -- do not lean on it.
    source TEXT NOT NULL
);
CREATE INDEX idx_versification_ref ON versification_map(work_id, book, chapter, verse);

CREATE TABLE grammar_articles (     -- unfoldingWord Hebrew Grammar, one row per article.
                                    -- The lexicons in this database say what a WORD means; this
                                    -- says what a FORM does, which develop-bible-study's Phase 4
                                    -- asks for and nothing here previously supplied.
    work_id TEXT NOT NULL REFERENCES works(work_id),
    slug TEXT NOT NULL,              -- file stem, e.g. 'adjective_gentilic'
    title TEXT NOT NULL,
    body TEXT NOT NULL,              -- reStructuredText with its directives stripped to prose
    PRIMARY KEY (work_id, slug)
);
CREATE INDEX idx_grammar_slug ON grammar_articles(slug);

CREATE TABLE section_headings (     -- a translation's own section headings (BSB). Editorial: the
                                    -- translators' reading of where a passage turns, never Scripture
                                    -- and never to be quoted as it.
    work_id TEXT NOT NULL REFERENCES works(work_id),
    book TEXT NOT NULL,
    chapter INTEGER NOT NULL, verse INTEGER NOT NULL,          -- first verse under the heading
    end_chapter INTEGER NOT NULL, end_verse INTEGER NOT NULL,  -- last verse before the next heading
                                                               -- of the same or a higher level
    level TEXT NOT NULL,            -- 's1' section, 's2' sub-section, 'ms' major division (the five
                                    -- books of Psalms), 'd' a heading with no verse of its own,
                                    -- 'qa' an acrostic letter (Psalm 119)
    text TEXT NOT NULL
);
CREATE INDEX idx_headings_ref ON section_headings(book, chapter, verse);

CREATE TABLE parallel_passages (    -- passages the translators mark as telling the same thing:
                                    -- the synoptic gospels, Kings beside Chronicles, a psalm beside
                                    -- the narrative it belongs to. One row per target, from the BSB's
                                    -- parallel-passage line under a section heading; the from-range
                                    -- is that section.
    work_id TEXT NOT NULL REFERENCES works(work_id),
    book TEXT NOT NULL,
    chapter INTEGER NOT NULL, verse INTEGER NOT NULL,
    end_chapter INTEGER NOT NULL, end_verse INTEGER NOT NULL,
    heading TEXT,                   -- the section heading the line sits under
    to_book TEXT NOT NULL,
    to_chapter INTEGER NOT NULL, to_verse INTEGER NOT NULL,
    to_end_chapter INTEGER NOT NULL, to_end_verse INTEGER NOT NULL
);
CREATE INDEX idx_parallels_ref ON parallel_passages(book, chapter, verse);
CREATE INDEX idx_parallels_to ON parallel_passages(to_book, to_chapter, to_verse);

CREATE TABLE proper_names (         -- every individual person, place and named thing, from STEP's
                                    -- TIPNR. One row per INDIVIDUAL, not per name: the eight
                                    -- Zechariahs are eight rows, which is the point.
    work_id TEXT NOT NULL REFERENCES works(work_id),
    name_id TEXT NOT NULL,          -- STEP's unique name, e.g. 'Aaron@Exo.4.14-Heb' (first mention)
    kind TEXT NOT NULL,             -- 'person' | 'place' | 'person+place' | 'other'
    name TEXT NOT NULL,
    strongs TEXT,                   -- STEP's disambiguated Strong's for the name ('H0175')
    description TEXT,               -- person/other: 'High Priest living at the time of ...'
    type TEXT,                      -- person: Male/Female; place: Place; other: Supernatural, Language ...
    parents TEXT,                   -- these four hold name_ids, comma-separated. A suffix marks a
    siblings TEXT,                  -- looser link: (a) ancestor rather than parent, (d) a people
    partners TEXT,                  -- descended from them, (f) founder, (?) STEP's judgment on an
    offspring TEXT,                 -- ambiguous text. Read those before treating a link as a fact.
    group_or_area TEXT,             -- person: tribe or nation; place: geographical area
    founder TEXT,                   -- place only
    inhabitants TEXT,               -- place only
    summary TEXT,                   -- STEP's one-paragraph summary, assembled from the fields above
    brief TEXT                      -- STEP's '@Brief' line
);
CREATE INDEX idx_names_name ON proper_names(name COLLATE NOCASE);
CREATE UNIQUE INDEX idx_names_id ON proper_names(work_id, name_id);

CREATE TABLE name_references (      -- every verse naming an individual, so 'which Zechariah is in
                                    -- this verse?' has an answer
    work_id TEXT NOT NULL REFERENCES works(work_id),
    name_id TEXT NOT NULL,
    book TEXT NOT NULL, chapter INTEGER NOT NULL, verse INTEGER NOT NULL,
    strongs TEXT,
    form TEXT                       -- the Hebrew/Greek form named, when the source gives one
);
CREATE INDEX idx_namerefs_ref ON name_references(book, chapter, verse);
CREATE INDEX idx_namerefs_id ON name_references(name_id);

CREATE TABLE place_locations (      -- where a biblical place is thought to be, from OpenBible.info.
                                    -- An identification is a scholar's judgment, often disputed:
                                    -- score says how confident, alternatives what else is proposed.
    work_id TEXT NOT NULL REFERENCES works(work_id),
    place_id TEXT NOT NULL,         -- OpenBible's own id
    name TEXT NOT NULL,
    name_id TEXT,                   -- the TIPNR name_id OpenBible links, when it links one
    types TEXT,                     -- comma-separated: settlement, river, mountain ...
    modern_name TEXT,               -- the best-scoring identification
    lon REAL, lat REAL,
    score INTEGER,                  -- OpenBible's confidence in that identification, 0-1000
    alternatives TEXT,              -- JSON list of [modern_name, score] for the rest
    verses TEXT                     -- semicolon-separated 'Book C:V', as OpenBible lists them
);
CREATE INDEX idx_places_name ON place_locations(name COLLATE NOCASE);
CREATE INDEX idx_places_nameid ON place_locations(name_id);
